import{Component}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{THREE,mesh,slab,materials,solid,hole,roundedRect,annulus}from'./geometry.js';import{grove,sma,dc}from'./connectors.js';import{LTEAntenna,GNSSAntenna}from'./Antenna.js';import{addStickers}from'./stickers.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';const tau=Math.PI*2;
function board(host){const s=new THREE.Shape(),e=17.5,r=3.5,y=-17,a=Math.acos((e-16)/r),dy=Math.sqrt(r*r-(e-16)**2);s.moveTo(-12,21);s.lineTo(12,21);s.lineTo(e,18);s.lineTo(e,y+dy);s.absarc(16,y,r,a,Math.PI,false);s.lineTo(12,-21);s.lineTo(-12,-21);s.lineTo(-12.5,y);s.absarc(-16,y,r,0,Math.PI-a,false);s.lineTo(-e,18);s.lineTo(-12,21);s.closePath();for(const x of[-9,-7,-5,-3])hole(s,x,-20,.45);const green=materials.plastic(0x245c3e,{roughness:.9}),dark=materials.plastic(0x171e18),tin=materials.metal(0xb8bdab),gold=materials.metal(0xc1aa63),top=spec.pcb.topZ,pcb=solid(host.body,s,.8,[0,0,top-.8],green,'CatM GNSS own inferred full carrier PCB with real boss reliefs and4Grove solderdrills'),pads=[],barrels=[];for(const x of[-9,-7,-5,-3]){barrels.push(mesh(host.body,annulus(.45,.28,.8),tin,[x,-20,top-.8],'CatM GNSS actual Grove plated barrel'));for(const z of[top,top-.86])pads.push(mesh(host.body,annulus(.7,.28,.06),tin,[x,-20,z],'CatM GNSS actual annular Grove solderland'));}
const module=slab(host.body,17.6,15.7,.55,.1,spec.module.position,dark,[],0);module.name='CatM GNSS exact SIM7080G substrate footprint,installedpose inferred';const shield=slab(host.body,16.9,15,1.75,.15,[0,1,top+.55],materials.metal(0xbcc2b5,{roughness:.66}),[],.025);shield.name='CatM GNSS exact SIM7080G metal shield envelope';const lands=[];for(const side of[-1,1])for(let i=0;i<12;i++)lands.push(mesh(host.body,new THREE.BoxGeometry(.7,.42,.08),gold,[side*8.55,1+(i-5.5)*1.13,top+.04],'CatM GNSS SIM7080G perimeter land appearance,no pinmap'));
const converters=[],inductors=[],bulk=[],secondary=[],internalLEDs=[];for(const[x,y]of[[-11,-12],[10,-11]]){const c=slab(host.body,3.2,3.1,.9,.1,[x,y,top],dark,[],0);c.name='CatM GNSS exact schematic ME3116AM6G converter inferredinstallation';converters.push(c);const ind=slab(host.body,4.5,4.5,2.2,.3,[x<0?-13:13,y+5.2,top],materials.plastic(0x4a5147),[],0);ind.name='CatM GNSS exact schematic10uH inductor envelope';inductors.push(ind);}for(const x of[-13,13]){const c=mesh(host.body,new THREE.CylinderGeometry(2.6,2.6,6.3,40).rotateX(Math.PI/2),tin,[x,-1,top+3.15],'CatM GNSS exact schematic470uF bulkcapacitor inferred package');bulk.push(c);mesh(host.body,new THREE.CylinderGeometry(2.3,2.3,.18,40).rotateX(Math.PI/2),dark,[x,-1,top+6.39],'CatM GNSS capacitor fixed top vent carrier');}
for(const[n,x,y,w,h]of[['SMF05C SIM protection',11,13,2.6,2],['UART SS8050 transistor',-11,10,2.1,1.3],['UART SS8050 transistor',-11,14,2.1,1.3],['STATUS SS8050 transistor',-2,15,2.1,1.3],['NETLIGHT SS8050 transistor',3,15,2.1,1.3],['B5819W rectifier',0,-12,2.5,1.3],['TVS SD24',14,-14,2.1,1.3]]){const q=slab(host.body,w,h,.65,.1,[x,y,top],dark,[],0);q.name='CatM GNSS exactschematic '+n+' inferredplacement';secondary.push(q);}for(let i=0;i<18;i++){const x=-12+(i%9)*3,y=-15.2-Math.floor(i/9)*2.3,q=slab(host.body,1.25,.7,.4,.05,[x,y,top],i%2?dark:materials.plastic(0xb3a17b),[],0);q.name='CatM GNSS schematic secondary passive envelope,notcompleteBOM';secondary.push(q);for(const sign of[-1,1])secondary.push(mesh(host.body,new THREE.BoxGeometry(.18,.7,.42),tin,[x+sign*.53,y,top+.21],'CatM GNSS passive actual metaltermination'));}for(const[x,name]of[[-1.8,'D3 NETLIGHT'],[1.8,'D2 STATUS']]){const q=slab(host.body,1.6,.8,.5,.05,[x,18.1,top],materials.plastic(0xb4bda7),[],0);q.name='CatM GNSS '+name+' actual schematic carrier nonemissive,unconfirmedopticalpath';internalLEDs.push(q);}return{pcb,pads,barrels,module,shield,lands,converters,inductors,bulk,secondary,internalLEDs};}
function sim(host){const frame=new THREE.Group();frame.name='CatM GNSS actual side entry MicroSIM holder,nocardsupplied';frame.position.fromArray(spec.sim.holderCentre);host.body.add(frame);const black=materials.plastic(0x141a16),silver=materials.metal(0xb9bfaf),gold=materials.metal(0xc1a55c),base=slab(frame,15.0,15.0,.3,.25,[-1.3,0,-.32],black,[],0);base.name='CatM GNSS inferred MicroSIM actual dielectricbacking';const rails=[];for(const y of[-7.7,7.7])rails.push(mesh(frame,new THREE.BoxGeometry(14.7,.65,1),black,[-1.3,y,-.9],'CatM GNSS MicroSIM retained side guide'));const end=mesh(frame,new THREE.BoxGeometry(.6,15.4,1.05),black,[-8.3,0,-.95],'CatM GNSS MicroSIM actual recessed dielectric endstop');const shape=roundedRect(15.2,15.5,.25);shape.holes.push(roundedRect(11,9,.4,{path:new THREE.Path(),clockwise:true}));const cover=solid(frame,shape,.18,[-1.3,0,-1.45],silver,'CatM GNSS real MicroSIM retained metal shell with inspectionwindow');const contacts=[];for(const x of[-3,3])for(const y of[-4,0,4])contacts.push(mesh(frame,new THREE.BoxGeometry(2.2,2.3,.14),gold,[x,y,-.55],'CatM GNSS six actual MicroSIM springcontactenvelopes'));const anchor=host.add(new Component({id:'sim',label:'MicroSIM side socket · no card supplied',position:spec.sim.mouth,meta:{role:'visual-anchor',cardType:'MicroSIM',cardIncluded:false,scope:'Passive actual side-slot location only;no carddata,card insertion state,network,RF,electrical orfirmware behavior.'}}));return{frame,base,rails,end,cover,contacts,anchor};}
function fixing(host){const out=[],metal=materials.metal(0xb6bdae);for(const[x,y]of spec.rearCover.screws){const s=new THREE.Shape();s.absarc(0,0,1.45,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=i*tau/6;i?h.lineTo(.63*Math.cos(a),.63*Math.sin(a)):h.moveTo(.63*Math.cos(a),.63*Math.sin(a));}h.closePath();s.holes.push(h);out.push({head:solid(host.body,s,.42,[x,y,-7.25],metal,'CatM GNSS own rear hexsocket fixinghead'),floor:mesh(host.body,new THREE.CylinderGeometry(.64,.64,.1,6).rotateX(Math.PI/2),materials.metal(0x626e60),[x,y,-6.77],'CatM GNSS recessed actual hexsocketfloor'),shank:mesh(host.body,new THREE.CylinderGeometry(.58,.58,6.2,32).rotateX(Math.PI/2),metal,[x,y,-3.6],'CatM GNSS retained originalrear fixing shaft')});}return out;}
function labels(host,rear){const films={},silver=materials.plastic(0xdadcd5,{roughness:.84}),s=new THREE.Shape();s.moveTo(-16,18);s.lineTo(16,18);s.quadraticCurveTo(17,18,17,17);s.lineTo(17,-18.8);s.quadraticCurveTo(17,-19.8,16,-19.8);s.lineTo(11.5,-19.8);s.lineTo(11.5,-24.6);s.lineTo(-11.5,-24.6);s.lineTo(-11.5,-19.8);s.lineTo(-16,-19.8);s.quadraticCurveTo(-17,-19.8,-17,-18.8);s.lineTo(-17,17);s.quadraticCurveTo(-17,18,-16,18);s.closePath();films.front=solid(host.body,s,.07,[0,0,7.2],silver,'CatM GNSS independent physical diecut front labelsubstrate');if(rear){films.back=slab(host.body,21.8,14.1,.07,.05,[0,11.8,-7.47],materials.plastic(0xf4f5ed),[],0);films.back.name='CatM GNSS independent physical rear compliance labelsubstrate';}for(const f of Object.values(films))f.userData.role='physical-label-substrate';return films;}
export function buildCatMGNSS(host,{rearCover=true,lteAntenna=false,gnssAntenna=false,lteAngleDeg=0,gnssPose,gnssCable}={}){for(const q of[rearCover,lteAntenna,gnssAntenna])if(typeof q!=='boolean')throw new TypeError('rearCover/lteAntenna/gnssAntenna must be boolean');if(!Number.isFinite(lteAngleDeg)||lteAngleDeg<0||lteAngleDeg>90)throw new RangeError('lteAngleDeg must be0…90');const parts=addCadParts(host,data.filter(p=>rearCover||p.role==='front'),{shell:materials.plastic(0x484c46,{roughness:.88})}),pcb=board(host),socket=grove(host),power=dc(host),gnss=sma(host,'gnss',spec.sma.gnss),lte=sma(host,'lte',spec.sma.lte),holder=sim(host),screws=rearCover?fixing(host):[],films=labels(host,rearCover);host.catmGnssAssembly={rearCover,parts,board:pcb,socket,dc:power,gnss,lte,sim:holder,screws,films};host.unitStickers=addStickers(host);if(lteAntenna)lte.port.attach(new LTEAntenna({angleDeg:lteAngleDeg}));if(gnssAntenna)gnss.port.attach(new GNSSAntenna({artwork:host.options.artwork,puckPose:gnssPose,cable:gnssCable}));}
